contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount > 0);
        uint256 supplyBefore = c.totalSupply();
        uint256 ownerBalBefore = c.balanceOf(address(this));
        require(ownerBalBefore >= amount);

        bool reverted;
        try c.burn(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 ownerBalAfter = c.balanceOf(address(this));

        if (!reverted) {
            assert(supplyAfter == supplyBefore - amount);
            assert(ownerBalAfter == ownerBalBefore - amount);
        } else {
            assert(supplyAfter == supplyBefore);
            assert(ownerBalAfter == ownerBalBefore);
        }
    }
}

